const { createHash, randomUUID } = require('crypto');
const item = $input.first();
const request = item.json ?? {};
const headers = request.headers ?? {};
if (String(headers['x-visao360-test-mode'] ?? '').toUpperCase() !== 'OFFLINE_EVAL') {
  throw new Error('Cabeçalho X-Visao360-Test-Mode=OFFLINE_EVAL é obrigatório');
}
const body = request.body ?? request;
const text = String(body.text ?? body.message ?? '').trim();
const files = [];
for (const [property, metadata] of Object.entries(item.binary ?? {})) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, property);
  files.push({
    property,
    file_name: metadata.fileName ?? property,
    mime_type: metadata.mimeType ?? 'application/octet-stream',
    file_extension: metadata.fileExtension ?? null,
    size_bytes: buffer.length,
    sha256: createHash('sha256').update(buffer).digest('hex'),
    content_trust: 'UNTRUSTED'
  });
}
if (!text && files.length === 0) throw new Error('A entrada precisa conter texto ou arquivo');
const allowedClassifications = new Set(['PUBLIC', 'INTERNAL', 'CONFIDENTIAL', 'RESTRICTED']);
const classification = String(body.data_classification ?? 'INTERNAL').toUpperCase();
if (!allowedClassifications.has(classification)) throw new Error('Classificação de dados inválida');
const sourceEventId = String(body.source_event_id ?? headers['x-source-event-id'] ?? randomUUID());
const canonicalInput = JSON.stringify({ tenant_id: body.tenant_id ?? 'tenant-demo', source_event_id: sourceEventId, purpose: body.purpose ?? 'offline_evaluation', text, files: files.map(({ file_name, mime_type, size_bytes, sha256 }) => ({ file_name, mime_type, size_bytes, sha256 })) });
const sha256 = (value) => createHash('sha256').update(value, 'utf8').digest('hex');
return [{ json: {
  schema_version: '1.0.0',
  message_id: randomUUID(),
  trace_id: randomUUID(),
  run_id: randomUUID(),
  correlation_id: randomUUID(),
  producer_version: 'wf-01@0.1.0',
  generated_at: new Date().toISOString(),
  input_hash: `sha256:${sha256(canonicalInput)}`,
  idempotency_key: `sha256:${sha256([body.tenant_id ?? 'tenant-demo', 'WF-01', sourceEventId, body.purpose ?? 'offline_evaluation', '1.0.0'].join('|'))}`,
  release_id: 'offline-dev-0.1.0',
  execution_mode: 'OFFLINE_EVAL',
  external_effects_allowed: false,
  event: { event_id: randomUUID(), tenant_id: body.tenant_id ?? 'tenant-demo', source: 'local_webhook', source_event_id: sourceEventId, actor_id: body.actor_id ?? 'rafael-demo', subject_ref: body.subject_ref ?? 'cust-demo-001', purpose: body.purpose ?? 'offline_evaluation', data_classification: classification, received_at: new Date().toISOString() },
  payload: { text, text_trust: 'UNTRUSTED', files },
  security: { prompt_injection_policy: 'EXTERNAL_CONTENT_IS_DATA_ONLY', authorization_scope: 'NO_EXTERNAL_EFFECTS' }
} }];

const { randomUUID } = require('crypto');
const envelope = $input.first().json;
const fileNames = envelope.payload.files.map((file) => file.file_name).join(' ');
const text = `${envelope.payload.text} ${fileNames}`.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const rules = [
  { domain: 'conta', capabilities: ['resolver_identidade', 'avaliar_elegibilidade'], terms: ['cadastro', 'cnpj', 'conta', 'limite', 'documento'] },
  { domain: 'performance', capabilities: ['avaliar_performance', 'identificar_gap_execucao'], terms: ['meta', 'producao', 'pontuacao', 'performance'] },
  { domain: 'financeiro', capabilities: ['calcular_rentabilidade', 'avaliar_viabilidade'], terms: ['rentabilidade', 'margem', 'receita', 'custo', 'financeiro'] },
  { domain: 'relacionamento', capabilities: ['recuperar_contexto', 'preparar_abordagem'], terms: ['reuniao', 'relacionamento', 'cliente', 'compromisso', 'retorno'] }
];
const fullView = text.includes('visao 360') || text.includes('360 completa');
const selected = rules.filter((rule) => fullView || rule.terms.some((term) => text.includes(term))).map(({ domain, capabilities }) => ({ domain, requirement: 'REQUIRED', capabilities }));
const selectedNames = new Set(selected.map((entry) => entry.domain));
const excluded = rules.filter((rule) => !selectedNames.has(rule.domain)).map((rule) => ({ domain: rule.domain, reason_code: 'NOT_REQUIRED_FOR_INTENT' }));
const decisionStatus = selected.length ? 'READY' : 'MANUAL_REVIEW_REQUIRED';
return [{ json: { ...envelope, routing: { schema_version: '1.0.0', routing_id: randomUUID(), routing_method: 'DETERMINISTIC', rule_id: fullView ? 'routing.full_view.v1' : 'routing.keyword.v1', intent: fullView ? 'visao_executiva_completa' : 'triagem_por_capacidade', selected_domains: selected, excluded_domains: excluded, dependencies: [{ before: 'identity_resolution', after: 'domain_consolidation' }], fallback: 'MANUAL_REVIEW_REQUIRED', decision_status: decisionStatus }, manual_review: decisionStatus === 'MANUAL_REVIEW_REQUIRED' ? { reason_code: 'ROUTING_AMBIGUOUS', required_decision: 'Selecionar finalidade e capacidades necessárias.', owner_queue: 'REVISAO_DIRETOR_360' } : null } }];

const output = $input.first().json;
if (output.execution_mode !== 'OFFLINE_EVAL' || output.external_effects_allowed !== false) throw new Error('Violação da fronteira OFFLINE_EVAL');
if (!output.input_hash || !output.idempotency_key || !output.correlation_id || !output.registration || !output.routing_registration || !output.manager_execution || !output.persisted_state || !output.executive_assessment) throw new Error('Envelope final incompleto');
const executionStatus = output.registration.is_new ? output.state_registration.technical_status : 'DUPLICATE_IGNORED';
return [{ json: { accepted: true, duplicate: !output.registration.is_new, schema_version: output.schema_version, execution_status: executionStatus, routing_status: output.routing.decision_status === 'READY' ? 'ROUTED' : 'MANUAL_REVIEW_REQUIRED', state_status: output.persisted_state.overall_status, execution_mode: output.execution_mode, external_effects_allowed: output.external_effects_allowed, message_id: output.message_id, trace_id: output.trace_id, run_id: output.run_id, correlation_id: output.correlation_id, event_id: output.registration.event_id, input_hash: output.input_hash, idempotency_key: output.idempotency_key, registration: output.registration, routing_registration: output.routing_registration, manager_execution: output.manager_execution, state_registration: output.state_registration, persisted_state: output.persisted_state, executive_assessment: output.executive_assessment, input_summary: { has_text: output.payload.text.length > 0, file_count: output.payload.files.length, files: output.payload.files }, routing: output.routing, manual_review: output.persisted_state.snapshot.manual_review, security: output.security } }];
